<?php require_once '../includes/config.php';requireAdmin();$conn->query("UPDATE complaints SET is_escalated=1 WHERE status='Pending' AND is_escalated=0 AND date_submitted<=DATE_SUB(NOW(),INTERVAL 3 DAY)");if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$id=(int)($_POST['complaint_id']??0);$status=$_POST['new_status']??'';if($id&&in_array($status,['Pending','In Progress','Resolved'],true)){if($status==='Resolved'){$s=$conn->prepare('UPDATE complaints SET status=?,is_escalated=0,date_resolved=NOW() WHERE id=?');}else{$s=$conn->prepare('UPDATE complaints SET status=?,date_resolved=NULL WHERE id=?');}$s->bind_param('si',$status,$id);$s->execute();$s->close();flash('success','Complaint #'.$id.' updated.');}redirect('dashboard.php');}$stats=[];foreach(['Total'=>'','Pending'=>"WHERE status='Pending'",'Resolved'=>"WHERE status='Resolved'",'Escalated'=>'WHERE is_escalated=1'] as $k=>$where){$q=$conn->query('SELECT COUNT(*) c FROM complaints '.($where));$stats[$k]=(int)$q->fetch_assoc()['c'];}$q=$conn->query('SELECT c.*,u.name user_name,u.email user_email FROM complaints c JOIN users u ON u.id=c.user_id ORDER BY c.is_escalated DESC,c.date_submitted DESC');$rows=$q->fetch_all(MYSQLI_ASSOC);$title='Admin Dashboard';require '../includes/header.php';?><div class="hero"><div><h1>Complaint control center</h1><p class="subtitle">Review, update and prioritize every complaint.</p></div></div><div class="stats"><div class="stat-card"><div class="label">Total</div><div class="value"><?=$stats['Total']?></div></div><div class="stat-card pending"><div class="label">Pending</div><div class="value"><?=$stats['Pending']?></div></div><div class="stat-card resolved"><div class="label">Resolved</div><div class="value"><?=$stats['Resolved']?></div></div><div class="stat-card escalated"><div class="label">Escalated</div><div class="value"><?=$stats['Escalated']?></div></div></div><div class="toolbar"><input data-filter="tbody tr" placeholder="Search complaints, users or categories..."><select data-status-filter="tbody tr"><option value="">All statuses</option><option>Pending</option><option>In Progress</option><option>Resolved</option></select><span class="subtitle"><?=count($rows)?> records</span></div><div class="table-card"><div class="table-wrap"><table><thead><tr><th>ID / Complaint</th><th>User</th><th>Category</th><th>Date</th><th>Status</th><th>Update</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6" class="empty">No complaints found.</td></tr><?php endif;foreach($rows as $r):?><tr data-status="<?=e($r['status'])?>" class="<?= $r['is_escalated']?'row-escalated':''?>"><td><a class="complaint-link" href="view.php?id=<?=$r['id']?>">#<?=$r['id']?> · <?=e(mb_strimwidth($r['description'],0,80,'…'))?></a><?php if($r['is_escalated']):?><div><span class="badge badge-escalated">Escalated</span></div><?php endif;?></td><td><?=e($r['user_name'])?><br><small><?=e($r['user_email'])?></small></td><td><span class="category-tag"><?=e($r['category'])?></span></td><td><?=date('d M Y',strtotime($r['date_submitted']))?></td><td><span class="badge <?=$r['status']==='Resolved'?'badge-resolved':($r['status']==='In Progress'?'badge-progress':'badge-pending')?>"><?=e($r['status'])?></span></td><td><form method="post" class="actions"><input type="hidden" name="csrf" value="<?=e(csrfToken())?>"><input type="hidden" name="complaint_id" value="<?=$r['id']?>"><select name="new_status"><option <?= $r['status']==='Pending'?'selected':''?>>Pending</option><option <?= $r['status']==='In Progress'?'selected':''?>>In Progress</option><option <?= $r['status']==='Resolved'?'selected':''?>>Resolved</option></select><button class="btn btn-primary">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php require '../includes/footer.php';?>
